const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; // 10" x 5.625"
pres.author = 'Gemini CLI';
pres.title = "Ultra Sound Money: Ethereum's Supply Dynamics";

// Theme Palette (Charcoal Minimal + Ocean Gradient inspired)
const colors = {
    bgDark: "0F172A",      // Deep slate/midnight
    bgLight: "F8FAFC",     // Off-white
    primary: "3B82F6",     // Blue
    accent: "10B981",      // Emerald green (positive/growth)
    accentWarn: "F59E0B",  // Amber (warning/low burn)
    textDark: "1E293B",
    textMutedDark: "64748B",
    textLight: "F1F5F9",
    textMutedLight: "94A3B8",
    cardBg: "FFFFFF",
    cardBorder: "E2E8F0"
};

// Global Helpers
const addHeader = (slide, text, subtitle = "") => {
    // Top banner
    slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.8, fill: { color: colors.bgDark } });

    // Main Title
    slide.addText(text, {
        x: 0.5, y: 0.15, w: 9, h: 0.4,
        fontSize: 24, fontFace: "Arial Black", color: colors.textLight,
        valign: "middle"
    });

    // Subtitle if provided
    if (subtitle) {
         slide.addText(subtitle, {
            x: 0.5, y: 0.55, w: 9, h: 0.2,
            fontSize: 12, fontFace: "Arial", color: colors.textMutedLight,
            valign: "middle"
        });
    }
};

const makeShadow = () => ({ type: "outer", color: "000000", blur: 4, offset: 2, angle: 45, opacity: 0.1 });

// --- Slide 1: Title Slide ---
let slide1 = pres.addSlide();
slide1.background = { color: colors.bgDark };

// Decorative background elements
slide1.addShape(pres.shapes.OVAL, { x: -1, y: -2, w: 6, h: 6, fill: { color: colors.primary, transparency: 85 } });
slide1.addShape(pres.shapes.OVAL, { x: 6, y: 2, w: 5, h: 5, fill: { color: colors.accent, transparency: 90 } });

slide1.addText("Ultra Sound Money", {
    x: 0.5, y: 1.5, w: 9, h: 0.8,
    fontSize: 48, fontFace: "Arial Black", color: colors.textLight, bold: true
});

slide1.addText("Ethereum's Supply Dynamics & Monetary Thesis", {
    x: 0.5, y: 2.4, w: 9, h: 0.5,
    fontSize: 24, fontFace: "Arial", color: colors.primary, bold: true
});

// Key Metrics Bar
const metricsY = 4.0;
const metricsW = 2.8;

// Metric 1: Supply
slide1.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: metricsY, w: metricsW, h: 1.0, fill: { color: "1E293B" } });
slide1.addText("Current Supply", { x: 0.5, y: metricsY + 0.1, w: metricsW, h: 0.3, fontSize: 14, color: colors.textMutedLight, align: "center" });
slide1.addText("121.6M ETH", { x: 0.5, y: metricsY + 0.4, w: metricsW, h: 0.5, fontSize: 28, fontFace: "Arial Black", color: colors.textLight, align: "center" });

// Metric 2: Price
slide1.addShape(pres.shapes.RECTANGLE, { x: 3.6, y: metricsY, w: metricsW, h: 1.0, fill: { color: "1E293B" } });
slide1.addText("ETH Price", { x: 3.6, y: metricsY + 0.1, w: metricsW, h: 0.3, fontSize: 14, color: colors.textMutedLight, align: "center" });
slide1.addText("$2,243", { x: 3.6, y: metricsY + 0.4, w: metricsW, h: 0.5, fontSize: 28, fontFace: "Arial Black", color: colors.textLight, align: "center" });

// Metric 3: Gas
slide1.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: metricsY, w: metricsW, h: 1.0, fill: { color: "1E293B" } });
slide1.addText("Current Base Gas", { x: 6.7, y: metricsY + 0.1, w: metricsW, h: 0.3, fontSize: 14, color: colors.textMutedLight, align: "center" });
slide1.addText("0.1 Gwei", { x: 6.7, y: metricsY + 0.4, w: metricsW, h: 0.5, fontSize: 28, fontFace: "Arial Black", color: colors.accentWarn, align: "center" });


// --- Slide 2: Supply Change Snapshot ---
let slide2 = pres.addSlide();
slide2.background = { color: colors.bgLight };
addHeader(slide2, "ETH Supply Growing at +0.83%/Year", "7-Day Snapshot: 192 ETH Burned vs 19,638 ETH Issued");

// Left Column: The Numbers
slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 4.2, h: 3.8, fill: { color: colors.cardBg }, shadow: makeShadow() });
slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.2, w: 0.1, h: 3.8, fill: { color: colors.primary } });

slide2.addText("7-Day Supply Change", { x: 0.8, y: 1.4, w: 3.6, h: 0.4, fontSize: 18, fontFace: "Arial Black", color: colors.textDark });

slide2.addText("Net Added", { x: 0.8, y: 2.0, w: 1.5, h: 0.3, fontSize: 14, color: colors.textMutedDark });
slide2.addText("+19,445.89 ETH", { x: 0.8, y: 2.3, w: 3.6, h: 0.5, fontSize: 28, fontFace: "Arial Black", color: colors.accentWarn });

slide2.addText("Current Total Supply", { x: 0.8, y: 3.0, w: 3.6, h: 0.3, fontSize: 14, color: colors.textMutedDark });
